(function() {
    THREE.CyberPostShader = {
        uniforms: {
            "tDiffuse": { value: null },
            "uResolution": { value: new THREE.Vector2( 1920, 1080 ) },
            "uTime": { value: 0.0 },
            "uChromaticStrength": { value: 0.0 },
            "uBarrelDistortion": { value: 0.0 },
            "uScanlineIntensity": { value: 0.0 },
            "uScanlineCount": { value: 800.0 },
            "uVignetteStrength": { value: 0.0 },
            "uScreenShake": { value: 0.0 }
        },
        vertexShader: [
            "varying vec2 vUv;",
            "void main() {",
            "   vUv = uv;",
            "   gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );",
            "}"
        ].join( "\n" ),
        fragmentShader: [
            "uniform sampler2D tDiffuse;",
            "uniform vec2 uResolution;",
            "uniform float uTime;",
            "uniform float uChromaticStrength;",
            "uniform float uBarrelDistortion;",
            "uniform float uScanlineIntensity;",
            "uniform float uScanlineCount;",
            "uniform float uVignetteStrength;",
            "uniform float uScreenShake;",

            "varying vec2 vUv;",

            "void main() {",
            "   vec2 uvWarped = vUv;",
            "   vec2 cc = vUv - 0.5;",
            
            "   if (uBarrelDistortion > 0.0) {",
            "       float dist = dot(cc, cc);",
            "       uvWarped = vUv + cc * dist * uBarrelDistortion;",
            "   }",

            "   if (uvWarped.x < 0.0 || uvWarped.x > 1.0 || uvWarped.y < 0.0 || uvWarped.y > 1.0) {",
            "       gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);",
            "       return;",
            "   }",

            "   vec3 color;",
            "   float totalChroma = clamp(uChromaticStrength + uScreenShake * 0.0008, 0.0, 0.0035);",
            "   float edgeDist = length(cc * 2.0);",
            "   float chromaEdge = smoothstep(0.5, 1.3, edgeDist) * totalChroma;",
            "   if (chromaEdge > 0.00005) {",
            "       vec2 dir = normalize(cc + 0.0001);",
            "       color.r = texture2D(tDiffuse, uvWarped + dir * chromaEdge).r;",
            "       color.g = texture2D(tDiffuse, uvWarped).g;",
            "       color.b = texture2D(tDiffuse, uvWarped - dir * chromaEdge).b;",
            "   } else {",
            "       color = texture2D(tDiffuse, uvWarped).rgb;",
            "   }",
            "",
            "   if (uScanlineIntensity > 0.0) {",
            "       float scanline = sin(uvWarped.y * uScanlineCount * 3.14159) * 0.5 + 0.5;",
            "       scanline = pow(scanline, 1.5);",
            "       color *= 1.0 - uScanlineIntensity * (1.0 - scanline);",
            "       ",
            "       // RGB phosphor triads (only active when CRT mode is enabled)",
            "       float pixelX = uvWarped.x * uResolution.x;",
            "       float phosphor = mod(pixelX, 3.0);",
            "       vec3 rgbIntensity = vec3(1.0);",
            "       if (phosphor < 1.0) {",
            "           rgbIntensity = vec3(1.0, 0.85, 0.85);",
            "       } else if (phosphor < 2.0) {",
            "           rgbIntensity = vec3(0.85, 1.0, 0.85);",
            "       } else {",
            "           rgbIntensity = vec3(0.85, 0.85, 1.0);",
            "       }",
            "       color *= mix(vec3(1.0), rgbIntensity, uScanlineIntensity * 0.4);",
            "   }",
            "",
            "   if (uVignetteStrength > 0.0) {",
            "       float vignette = smoothstep(1.3, 0.55, length(cc * 1.6));",
            "       color *= mix(1.0, vignette, uVignetteStrength);",
            "   }",
            "",
            "   gl_FragColor = vec4(color, 1.0);",
            "}"
        ].join( "\n" )
    };
})();
